import{_ as e,o,c as r,ah as a}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Cohorts","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/coordinateur/cohortes.md","filePath":"src/en/guide/coordinateur/cohortes.md"}'),n={name:"en/guide/coordinateur/cohortes.md"};function s(i,t,h,d,l,c){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="cohorts" tabindex="-1">Cohorts <a class="header-anchor" href="#cohorts" aria-label="Permalink to &quot;Cohorts&quot;">​</a></h1><p>A cohort is a scheduled session of a program, attached to a promotion. It has <strong>15 learners at most</strong> and can mix the three formats: the format and price are carried by each enrolment, not by the cohort.</p><h2 id="opening-a-cohort" tabindex="-1">Opening a cohort <a class="header-anchor" href="#opening-a-cohort" aria-label="Permalink to &quot;Opening a cohort&quot;">​</a></h2><p><strong>Training → Cohorts → Open a cohort.</strong> The form lists the programs and shows, for each, what prevents it from opening:</p><ul><li>program <strong>not published</strong>;</li><li><strong>QCM bank not validated</strong>;</li><li><strong>price missing</strong> from the grid for an offered format.</li></ul><p>Then fill in:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Promotion and year</td><td>Baobab (September), Iroko (December), Acacia (March) or Karité (June). One cohort per program, promotion and year</td></tr><tr><td>Dates</td><td>Start and end. The end at the earliest at the program&#39;s duration (25 or 12 weeks); part-time lengthens it, enter the real date</td></tr><tr><td>Pace profile</td><td>Full-time or part-time, for information</td></tr><tr><td>Lead trainers</td><td>At least one. Mandatory</td></tr><tr><td>Coach-tutors</td><td>Optional</td></tr></tbody></table><p>On opening, <strong>the grid prices are frozen</strong> on the cohort. The mid-point and the dates of the three instalments (30/40/30) are <strong>calculated</strong>, never entered: 30% at the start (or at signing if later), 40% at the mid-point, 30% at the end.</p><h2 id="the-life-cycle" tabindex="-1">The life cycle <a class="header-anchor" href="#the-life-cycle" aria-label="Permalink to &quot;The life cycle&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What triggers it</th></tr></thead><tbody><tr><td><strong>Open</strong></td><td>On opening</td></tr><tr><td><strong>Confirmed</strong></td><td>You click <strong>Confirm</strong></td></tr><tr><td><strong>In progress</strong></td><td>Automatically, on the start date of a confirmed cohort</td></tr><tr><td><strong>Completed</strong></td><td>Automatically, after its end date. Its active and suspended enrolments become &quot;completed&quot;</td></tr><tr><td><strong>Postponed</strong>, <strong>Cancelled</strong></td><td>You decide, before the start</td></tr></tbody></table><p>Dates, pace and staffing stay editable <strong>until the start</strong>; frozen prices do not change.</p><h3 id="postponing-or-cancelling" tabindex="-1">Postponing or cancelling <a class="header-anchor" href="#postponing-or-cancelling" aria-label="Permalink to &quot;Postponing or cancelling&quot;">​</a></h3><p>A <strong>postponement</strong> or <strong>cancellation</strong> is only possible before the start, with a <strong>mandatory reason</strong>, and the decision is <strong>final</strong> and logged.</p><ul><li><strong>Postponement</strong>: you choose the <strong>replacement cohort</strong>, an upcoming cohort of the same program, with a seat and a price for each learner. All non-dropped enrolments move there.</li><li><strong>Cancellation</strong>: enrolments become &quot;without cohort&quot;. You place each learner again or record their drop-out.</li></ul><p>The financial consequences follow the billing rules (see <a href="./facturation.html#if-a-cohort-changes-or-is-cancelled">Billing</a>).</p><h2 id="the-cohort-s-seve-course" tabindex="-1">The cohort&#39;s Sève course <a class="header-anchor" href="#the-cohort-s-seve-course" aria-label="Permalink to &quot;The cohort&#39;s Sève course&quot;">​</a></h2><p>On the cohort page, enter the <strong>Sève course id</strong>. Each learner is enrolled in it as soon as their first instalment is paid; without an id, their enrolments wait. It is also needed for virtual classes and grades to flow back into Kura.</p><h2 id="profitability-zones" tabindex="-1">Profitability zones <a class="header-anchor" href="#profitability-zones" aria-label="Permalink to &quot;Profitability zones&quot;">​</a></h2><p>Kura classifies each cohort by its <strong>confirmed headcount</strong> (signed enrolments):</p><table tabindex="0"><thead><tr><th>Zone</th><th>Default headcount</th></tr></thead><tbody><tr><td>Fragile</td><td>Fewer than 7</td></tr><tr><td>Viable</td><td>7 to 11</td></tr><tr><td>Comfortable</td><td>12 to 15</td></tr></tbody></table><p>The Administrator sets the thresholds per category. A cohort that starts <strong>freezes its zone</strong> with its headcount: a threshold change only touches upcoming cohorts.</p><h3 id="the-profitability-dashboard" tabindex="-1">The profitability dashboard <a class="header-anchor" href="#the-profitability-dashboard" aria-label="Permalink to &quot;The profitability dashboard&quot;">​</a></h3><p><strong>Training → Profitability</strong> presents open and confirmed cohorts, with:</p><ul><li>their zone and headcount against the thresholds;</li><li>the <strong>signed revenue</strong>, and that awaiting signature;</li><li>the <strong>staffing cost</strong> and the share covered by revenue;</li><li>a cohort <strong>&quot;To decide&quot;</strong>: fragile less than a week before the start, placed first.</li></ul><p>In the fragile zone, the dashboard recommends considering a postponement. <strong>It triggers nothing</strong>: the decision is yours.</p><h2 id="the-cohort-page" tabindex="-1">The cohort page <a class="header-anchor" href="#the-cohort-page" aria-label="Permalink to &quot;The cohort page&quot;">​</a></h2><p>The page gathers the calendar, schedule, frozen prices, the Sève course, staffing, learners (with the &quot;No image rights&quot; marker), and links to <strong>attendance</strong> and <strong>results</strong>.</p><p>The <strong>Documents</strong> panel generates on demand:</p><ul><li>the <strong>provisional calendar</strong> (for everyone who sees the cohort);</li><li>the <strong>activity report</strong>: seats, attendance, results (for you and the Administrator);</li><li>the <strong>defence report</strong>, see <a href="./resultats.html">Results and certification</a>.</li></ul>',29)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
